import math

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau(n):
    factors = prime_factorization(n)
    num_divisors = 1
    for exponent in factors.values():
        num_divisors *= (exponent + 1)
    return num_divisors

# Check k from 1 to 25
results = {}
for k in range(1, 26):
    N = 2 * (k**3)
    tau_N = tau(N)
    target = 2 * k
    is_success = tau_N == target
    results[k] = {
        "N": N,
        "tau(N)": tau_N,
        "2k": target,
        "Success": is_success
    }

# Print results clearly for recording
print("--- Results ---")
for k, res in results.items():
    status = "SUCCESS" if res["Success"] else "FAILURE"
    print(f"k={k}: N={res['N']}, tau(N)={res['tau(N)']}, 2k={res['2k']}, Status: {status}")

# List successes
successes = [k for k, res in results.items() if res["Success"]]
print("\nSuccessful k values found:", successes)

