print(f"Solutions found: {solutions}")

def get_tau(n):
    """Calculates the number of divisors (tau) of an integer n."""
    if n <= 0:
        return 0
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    tau = 1
    for exponent in factors.values():
        tau *= (exponent + 1)
    return tau

k_values = [1, 4, 10]
results = {}

print("--- Verification of tau(2k^3) = 2k ---")
for k in k_values:
    target_tau = 2 * k
    n = 2 * (k**3)
    calculated_tau = get_tau(n)

    print(f"\nTesting k = {k}:")
